from collections import defaultdict

# Regrouper des commandes par client : O(n) au lieu de O(n²)
def group_by_customer(orders):
    groups = defaultdict(list)          # clé -> liste
    for order_id, customer in orders:   # une seule boucle
        groups[customer].append(order_id)
    return dict(groups)

print(group_by_customer([(1, 'a'), (2, 'b'), (3, 'a')]))
# {'a': [1, 3], 'b': [2]}

# Existe-t-il deux montants (liste triée) dont la somme vaut target ?
def has_pair(sorted_amounts, target):
    i, j = 0, len(sorted_amounts) - 1
    while i < j:
        s = sorted_amounts[i] + sorted_amounts[j]
        if s == target:
            return True
        if s < target:
            i += 1          # il faut plus grand
        else:
            j -= 1          # il faut plus petit
    return False

print(has_pair([1, 3, 4, 6, 9], 10))  # True (1 + 9)

# Supprimer les doublons adjacents, en cascade : 'abbaca' -> 'ca'
def remove_adjacent(s):
    stack = []
    for ch in s:
        if stack and stack[-1] == ch:
            stack.pop()       # le doublon s'annule
        else:
            stack.append(ch)
    return ''.join(stack)

