from collections import deque

# Valeurs niveau par niveau (BFS)
def levels(root):
    if not root:
        return []
    out, q = [], deque([root])
    while q:
        level = []
        for _ in range(len(q)):        # exactement un niveau
            n = q.popleft()
            level.append(n.val)
            if n.left: q.append(n.left)
            if n.right: q.append(n.right)
        out.append(level)
    return out

from collections import deque

# Ordre d'exécution des jobs (tri topologique de Kahn)
def run_order(deps):              # deps: job -> liste de jobs requis
    jobs = set(deps) | {d for ds in deps.values() for d in ds}
    indeg = {j: 0 for j in jobs}
    after = {j: [] for j in jobs}
    for j, ds in deps.items():
        for d in ds:
            after[d].append(j); indeg[j] += 1
    q = deque(sorted(j for j in jobs if indeg[j] == 0))
    order = []
    while q:
        j = q.popleft(); order.append(j)
        for k in after[j]:
            indeg[k] -= 1
            if indeg[k] == 0: q.append(k)
    return order if len(order) == len(jobs) else 'CYCLE'

print(run_order({'report': ['clean'], 'clean': ['extract']}))

# Cambrioleur : maximum sans prendre deux maisons voisines
def rob(values):
    take, skip = 0, 0          # meilleur total si je prends / saute la maison courante
    for v in values:
        take, skip = skip + v, max(take, skip)
    return max(take, skip)

# dp[i] = max(dp[i-1], dp[i-2] + values[i])
print(rob([2, 7, 9, 3, 1]))  # 12 (2 + 9 + 1)

# Glouton : nombre max de jobs sans chevauchement sur une machine
def max_jobs(jobs):                        # [start, end]
    count, free_at = 0, float('-inf')
    for s, e in sorted(jobs, key=lambda j: j[1]):   # par heure de FIN
        if s >= free_at:
            count += 1; free_at = e
    return count

# Trie minimal
def build_trie(words):
    root = {}
    for w in words:
        node = root
        for ch in w:
            node = node.setdefault(ch, {})
        node['$'] = True                     # fin de mot
    return root
